from concurrent.futures import ThreadPoolExecutor
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin
from urllib.request import Request, urlopen
import re

BASE = "https://agents-ml-course-2026.czuba-przemyslaw.chatgpt.site/"
DEST = Path("work/course")
DEST.mkdir(parents=True, exist_ok=True)
PAGES = ["lab-1-introduction", "lab-1.html", "index.html", "organizacja.html",
         "przygotowanie.html", "oddawanie.html", "repertoire.html", "prompting.html",
         "poznawanie-tematu.html", "podejmowanie-decyzji.html", "powierzanie-decyzji.html",
