         "lab-2.html", "lab-3-introduction.html", "lab-3.html",
         "lab-4-introduction.html", "lab-4.html", "lab-5.html"]

class Reader(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_main = False
        self.parts = []
        self.links = []
        self.in_pre = False
        self.hide = False

    def handle_starttag(self, tag, attrs):
        if tag == "main":
            self.in_main = True
        if not self.in_main:
            return
        if tag in {"script", "style", "svg"}:
            self.hide = True
        if self.hide:
            return
        attrs = dict(attrs)
        if tag in {"h1","h2","h3","h4","p","ul","ol","details","summary","aside","figcaption","tr", "section", "div"}:
            self.parts.append("\n")
        if tag == "li":
            self.parts.append("\n- ")
        if tag == "a":
            self.links.append(attrs.get("href", ""))
        if tag == "img":
            self.links.append(attrs.get("src", ""))
            if attrs.get("alt"):
                self.parts.append(f' [obraz: {attrs["alt"]}] ')
        if tag in {"td","th"}:
            self.parts.append(" | ")
        if tag == "br":
            self.parts.append("\n")
        if tag == "pre":
            self.parts.append("\n[code]\n")
            self.in_pre = True

    def handle_endtag(self, tag):
        if tag == "main":
            self.in_main = False
        if tag in {"script", "style", "svg"}:
            self.hide = False
        if not self.in_main or self.hide:
            return
        if tag in {"h1","h2","h3","h4","p","ul","ol","aside","figcaption","tr", "section", "div", "li","summary"}:
            self.parts.append("\n")
        if tag == "pre":
            self.parts.append("\n[/code]\n")
            self.in_pre = False
        if tag == "a":
            self.parts.append(f" [link {len(self.links)}]")

    def handle_data(self, data):
        if self.in_main and not self.hide:
            self.parts.append(data if self.in_pre else re.sub(r"\s+"," ",data))

    def get_text(self):
        return re.sub(r"\n\s*\n+", "\n\n", "".join(self.parts)).strip()

def page(name):
    url = urljoin(BASE, name)
    req = Request(url, headers={"User-Agent": "Mozilla/5.0"})
    try:
        with urlopen(req, timeout=20) as response:
            source = response.read().decode("utf-8")
            parser = Reader()
            parser.feed(source)
            body = parser.get_text()
            links = "\n".join(f"{i}. {urljoin(url, target)}" for i,target in enumerate(parser.links, 1))
            (DEST / (name + ".txt")).write_text(body + "\n\nLINKS\n" + links, encoding="utf-8")
            (DEST / (name + ".source")).write_text(source, encoding="utf-8")
            return f"{name}: {response.status} {len(body)} chars {len(parser.links)} links"
    except Exception as exc:
        return f"{name}: {exc}"

with ThreadPoolExecutor(max_workers=8) as pool:
    for line in pool.map(page, PAGES):
        print(line)
